    op.create_table(
        "product_runs",
        sa.Column("id", sa.String(length=36), nullable=False),
        sa.Column("workspace_id", sa.String(length=36), nullable=False),
        sa.Column("owner_user_id", sa.String(length=36), nullable=False),
        sa.Column("session_id", sa.String(length=36), nullable=False),
        sa.Column("turn_user_message_id", sa.String(length=36), nullable=True),
        sa.Column("origin", sa.String(length=32), nullable=False),
        sa.Column("workspace_source", sa.String(length=32), nullable=False),
        sa.Column("state", sa.String(length=32), nullable=False),
        sa.Column("end_reason", sa.String(length=48), nullable=True),
        sa.Column("attempt_count", sa.Integer(), nullable=False),
        sa.Column("version", sa.Integer(), nullable=False),
        sa.Column("created_at", sa.DateTime(), nullable=False),
        sa.Column("updated_at", sa.DateTime(), nullable=False),
        sa.Column("ended_at", sa.DateTime(), nullable=True),
        sa.CheckConstraint(
            "end_reason IS NULL OR end_reason IN ('gate_denied', 'gate_missing_profile', 'gate_unknown_status', 'gate_needs_approval', 'gate_needs_configuration', 'gate_needs_clarification', 'runtime_not_ready', 'model_alias_not_admitted', 'model_data_policy_denied', 'preparation_failed', 'runtime_finished', 'provider_error', 'runtime_error', 'runtime_exception', 'approval_pending', 'clarification_requested', 'completion_not_accepted', 'delegated_outcome_unrecorded', 'generator_closed', 'task_cancelled', 'interrupted_by_restart', 'awaiting_workflow_confirmation')",
            name="ck_product_runs_end_reason",
        ),
        sa.CheckConstraint("origin IN ('chat_turn', 'sub_agent', 'scheduled_task')", name="ck_product_runs_origin"),
        sa.CheckConstraint(
            "state IN ('requested', 'admitted', 'running', 'verifying', 'completed', 'finished_unverified', 'failed', 'cancelled', 'denied', 'needs_approval', 'needs_configuration', 'needs_clarification', 'waiting_approval', 'incomplete')",
            name="ck_product_runs_state",
        ),
        sa.CheckConstraint("workspace_source IN ('session_project')", name="ck_product_runs_workspace_source"),
        sa.CheckConstraint("attempt_count >= 1", name="ck_product_runs_attempt_count"),
        sa.CheckConstraint("version >= 1", name="ck_product_runs_version"),
        sa.ForeignKeyConstraint(
            ["owner_user_id"],
            ["users.id"],
        ),
        sa.ForeignKeyConstraint(["session_id"], ["sessions.id"], ondelete="CASCADE"),
        sa.ForeignKeyConstraint(["workspace_id"], ["projects.id"], ondelete="RESTRICT"),
        sa.PrimaryKeyConstraint("id"),
    )
    op.create_index("ix_product_runs_owner_created", "product_runs", ["owner_user_id", "created_at"], unique=False)
    op.create_index("ix_product_runs_session_created", "product_runs", ["session_id", "created_at"], unique=False)
    op.create_index("ix_product_runs_state", "product_runs", ["state"], unique=False)
    op.create_index("ix_product_runs_workspace_created", "product_runs", ["workspace_id", "created_at"], unique=False)
