    op.create_table(
        "work_role_assignments",
        sa.Column("id", sa.String(length=36), nullable=False),
        sa.Column("project_id", sa.String(length=36), nullable=False),
        sa.Column("role_id", sa.String(length=36), nullable=False),
        sa.Column("subject_kind", sa.String(length=12), nullable=False),
        sa.Column("user_id", sa.String(length=36), nullable=True),
        sa.Column("group_id", sa.String(length=36), nullable=True),
        sa.Column("claim_value", sa.String(length=255), nullable=True),
        sa.Column("provider_id", sa.String(length=36), nullable=True),
        sa.Column("subject_key", sa.String(length=255), nullable=False),
        sa.Column("provider_key", sa.String(length=36), nullable=False),
        sa.Column("is_active", sa.Boolean(), nullable=False),
        sa.Column("version", sa.Integer(), nullable=False),
        sa.Column("created_by", sa.String(length=36), nullable=True),
        sa.Column("updated_by", sa.String(length=36), nullable=True),
        sa.Column("created_at", sa.DateTime(), nullable=False),
        sa.Column("updated_at", sa.DateTime(), nullable=False),
        sa.CheckConstraint(
            "(subject_kind = 'user' AND user_id IS NOT NULL AND group_id IS NULL AND claim_value IS NULL) OR (subject_kind = 'group' AND group_id IS NOT NULL AND user_id IS NULL AND claim_value IS NULL) OR (subject_kind IN ('sso_group','sso_role') AND claim_value IS NOT NULL AND user_id IS NULL AND group_id IS NULL)",
            name="ck_work_role_assign_subject",
        ),
        sa.CheckConstraint("subject_kind IN ('user','group','sso_group','sso_role')", name="ck_work_role_assign_kind"),
        sa.CheckConstraint("version >= 1", name="ck_work_role_assign_version"),
        sa.ForeignKeyConstraint(["created_by"], ["users.id"], ondelete="SET NULL"),
        sa.ForeignKeyConstraint(["group_id"], ["identity_groups.id"], ondelete="CASCADE"),
        sa.ForeignKeyConstraint(["project_id"], ["projects.id"], ondelete="CASCADE"),
        sa.ForeignKeyConstraint(["provider_id"], ["identity_providers.id"], ondelete="CASCADE"),
        sa.ForeignKeyConstraint(["role_id"], ["work_roles.id"], ondelete="CASCADE"),
        sa.ForeignKeyConstraint(["updated_by"], ["users.id"], ondelete="SET NULL"),
        sa.ForeignKeyConstraint(["user_id"], ["users.id"], ondelete="CASCADE"),
        sa.PrimaryKeyConstraint("id"),
        sa.UniqueConstraint(
            "project_id", "role_id", "subject_kind", "subject_key", "provider_key", name="uq_work_role_assignment"
        ),
    )
