        sa.CheckConstraint(
            "state != 'accepted' OR (accepted_by IS NOT NULL AND accepted_at IS NOT NULL AND receiver_session_id IS NOT NULL AND child_run_id IS NOT NULL AND owner_epoch >= 1)",
            name="ck_handoff_accepted_owner",
        ),
        sa.CheckConstraint(
            "state IN ('offered','accepted','timed_out','rejected','owner_lost','stopped','child_done')",
            name="ck_handoff_state",
        ),
        sa.CheckConstraint("target_kind IN ('person','role','group')", name="ck_handoff_target"),
        sa.CheckConstraint(
            "(child_run_id IS NULL AND receiver_session_id IS NULL) OR (child_run_id IS NOT NULL AND receiver_session_id IS NOT NULL)",
            name="ck_handoff_child_pair",
        ),
        sa.CheckConstraint("state_version >= 1 AND owner_epoch >= 0 AND round >= 1", name="ck_handoff_versions"),
