    op.create_table(
        "documentation_write_intents",
        sa.Column("id", sa.String(length=36), nullable=False),
        sa.Column("operation_id", sa.String(length=64), nullable=False),
        sa.Column("marker", sa.String(length=255), nullable=False),
        sa.Column("run_id", sa.String(length=36), nullable=False),
        sa.Column("slot", sa.String(length=64), nullable=False),
        sa.Column("node_id", sa.String(length=128), nullable=False),
        sa.Column("reserved_pass_key", sa.String(length=128), nullable=False),
        sa.Column("dispatch_pass_key", sa.String(length=128), nullable=True),
        sa.Column("decision_id", sa.String(length=36), nullable=True),
        sa.Column("card_hash", sa.String(length=71), nullable=True),
        sa.Column("output_hash", sa.String(length=71), nullable=True),
        sa.Column("body_hash", sa.String(length=71), nullable=True),
        sa.Column("connection_id", sa.String(length=64), nullable=False),
        sa.Column("instance", sa.String(length=500), nullable=False),
        sa.Column("space_id", sa.String(length=64), nullable=False),
        sa.Column("space_key", sa.String(length=255), nullable=True),
        sa.Column("parent_id", sa.String(length=64), nullable=True),
        sa.Column("page_id", sa.String(length=64), nullable=True),
        sa.Column("title", sa.String(length=255), nullable=False),
        sa.Column("operation", sa.String(length=10), nullable=False),
        sa.Column("base_version", sa.Integer(), nullable=True),
        sa.Column("expected_version", sa.Integer(), nullable=False),
        sa.Column("state", sa.String(length=32), nullable=False),
        sa.Column("state_version", sa.Integer(), server_default="0", nullable=False),
        sa.Column("claimed_by", sa.String(length=128), nullable=True),
        sa.Column("claimed_at", sa.DateTime(), nullable=True),
        sa.Column("dispatch_check", sa.JSON(), nullable=True),
        sa.Column("certified_by", sa.String(length=128), nullable=True),
        sa.Column("certified_at", sa.DateTime(), nullable=True),
        sa.Column("result_kind", sa.String(length=32), nullable=True),
        sa.Column("result_page_id", sa.String(length=64), nullable=True),
        sa.Column("result_version", sa.Integer(), nullable=True),
        sa.Column("result_location", sa.JSON(), nullable=True),
        sa.Column("result_storage_digest", sa.String(length=71), nullable=True),
        sa.Column("last_error_class", sa.String(length=40), nullable=True),
        sa.Column("last_error", sa.Text(), nullable=True),
        sa.Column("superseded_by_id", sa.String(length=36), nullable=True),
        sa.Column("created_at", sa.DateTime(), nullable=False),
        sa.Column("approved_at", sa.DateTime(), nullable=True),
        sa.Column("send_started_at", sa.DateTime(), nullable=True),
        sa.Column("pending_reconcile_at", sa.DateTime(), nullable=True),
        sa.Column("sent_confirmed_at", sa.DateTime(), nullable=True),
        sa.Column("superseded_at", sa.DateTime(), nullable=True),
        sa.Column("updated_at", sa.DateTime(), nullable=False),
        sa.CheckConstraint(
            "(operation = 'create' AND parent_id IS NOT NULL AND page_id IS NULL AND base_version IS NULL AND expected_version = 1) OR (operation = 'update' AND page_id IS NOT NULL AND base_version IS NOT NULL AND expected_version = base_version + 1)",
            name="ck_documentation_write_intents_target",
        ),
        sa.CheckConstraint(
            "(state IN ('send_started', 'sent_confirmed', 'pending_reconcile') AND claimed_by IS NOT NULL AND claimed_at IS NOT NULL AND send_started_at IS NOT NULL) OR (state NOT IN ('send_started', 'sent_confirmed', 'pending_reconcile') AND claimed_by IS NULL AND claimed_at IS NULL)",
            name="ck_documentation_write_intents_claim",
        ),
        sa.CheckConstraint("operation IN ('create', 'update')", name="ck_documentation_write_intents_operation"),
        sa.CheckConstraint(
            "result_kind IS NULL OR result_kind IN ('provider_reply', 'reconciled_adoption', 'desired_state_reached')",
            name="ck_documentation_write_intents_result_kind",
        ),
        sa.CheckConstraint(
            "state <> 'never_started_certified' OR (certified_by IS NOT NULL AND certified_at IS NOT NULL)",
            name="ck_documentation_write_intents_certified",
        ),
        sa.CheckConstraint(
            "state <> 'sent_confirmed' OR (result_page_id IS NOT NULL AND result_version IS NOT NULL AND result_kind IS NOT NULL AND sent_confirmed_at IS NOT NULL)",
            name="ck_documentation_write_intents_result",
        ),
        sa.CheckConstraint(
            "state <> 'superseded' OR superseded_at IS NOT NULL", name="ck_documentation_write_intents_superseded"
        ),
        sa.CheckConstraint(
            "state IN ('reserved', 'approved', 'send_started', 'sent_confirmed', 'pending_reconcile', 'never_started_certified', 'superseded')",
            name="ck_documentation_write_intents_state",
        ),
        sa.CheckConstraint(
            "state NOT IN ('approved', 'send_started', 'sent_confirmed', 'pending_reconcile', 'never_started_certified') OR (decision_id IS NOT NULL AND card_hash IS NOT NULL AND body_hash IS NOT NULL AND approved_at IS NOT NULL)",
            name="ck_documentation_write_intents_approved",
        ),
        sa.ForeignKeyConstraint(
            ["decision_id"],
            ["workflow_run_decisions.id"],
        ),
        sa.ForeignKeyConstraint(["run_id"], ["workflow_runs.id"], ondelete="CASCADE"),
        sa.ForeignKeyConstraint(
            ["superseded_by_id"],
            ["documentation_write_intents.id"],
        ),
        sa.PrimaryKeyConstraint("id"),
        sa.UniqueConstraint("marker"),
        sa.UniqueConstraint("operation_id"),
    )
