    op.create_table(
        "audience_receipts",
        sa.Column("id", sa.String(length=36), nullable=False),
        sa.Column("challenge_id", sa.String(length=64), nullable=False),
        sa.Column("run_id", sa.String(length=36), nullable=False),
        sa.Column("node_id", sa.String(length=128), nullable=False),
        sa.Column("pass_key", sa.String(length=128), nullable=False),
        sa.Column("intent_id", sa.String(length=36), nullable=False),
        sa.Column("publication_card_hash", sa.String(length=71), nullable=False),
        sa.Column("workspace_id", sa.String(length=36), nullable=False),
        sa.Column("connection_id", sa.String(length=64), nullable=False),
        sa.Column("instance", sa.String(length=500), nullable=False),
        sa.Column("source_key", sa.String(length=255), nullable=False),
        sa.Column("page_id", sa.String(length=64), nullable=False),
        sa.Column("page_version", sa.Integer(), nullable=False),
        sa.Column("revision_id", sa.String(length=64), nullable=False),
        sa.Column("revision_digest", sa.String(length=71), nullable=False),
        sa.Column("query_set", sa.JSON(), nullable=False),
        sa.Column("query_set_digest", sa.String(length=71), nullable=False),
        sa.Column("expected_principal_id", sa.String(length=36), nullable=False),
        sa.Column("issue_checks", sa.JSON(), nullable=False),
        sa.Column("consume_checks", sa.JSON(), nullable=True),
        sa.Column("state", sa.String(length=16), nullable=False),
        sa.Column("state_version", sa.Integer(), server_default="0", nullable=False),
        sa.Column("issued_at", sa.DateTime(), nullable=False),
        sa.Column("expires_at", sa.DateTime(), nullable=False),
        sa.Column("recorded_at", sa.DateTime(), nullable=True),
        sa.Column("recorded_by", sa.String(length=36), nullable=True),
        sa.Column("outcome", sa.String(length=16), nullable=True),
        sa.Column("hits", sa.JSON(), nullable=True),
        sa.Column("assertion_results", sa.JSON(), nullable=True),
        sa.Column("result_digest", sa.String(length=71), nullable=True),
        sa.Column("consumed_at", sa.DateTime(), nullable=True),
        sa.Column("consumed_by_run_id", sa.String(length=36), nullable=True),
        sa.Column("revoked_at", sa.DateTime(), nullable=True),
        sa.Column("revoke_reason", sa.String(length=64), nullable=True),
        sa.Column("updated_at", sa.DateTime(), nullable=False),
        sa.CheckConstraint(
            "(state = 'consumed' AND consumed_at IS NOT NULL AND consumed_by_run_id IS NOT NULL AND consumed_by_run_id = run_id) OR (state <> 'consumed' AND consumed_at IS NULL AND consumed_by_run_id IS NULL)",
            name="ck_audience_receipts_consumed",
        ),
        sa.CheckConstraint(
            "outcome IS NULL OR outcome IN ('positive', 'negative')", name="ck_audience_receipts_outcome"
        ),
        sa.CheckConstraint("state <> 'revoked' OR revoked_at IS NOT NULL", name="ck_audience_receipts_revoked"),
        sa.CheckConstraint(
            "state IN ('issued', 'recorded', 'consumed', 'revoked', 'expired')", name="ck_audience_receipts_state"
        ),
        sa.CheckConstraint(
            "state NOT IN ('recorded', 'consumed') OR (outcome IS NOT NULL AND recorded_at IS NOT NULL AND result_digest IS NOT NULL AND recorded_by IS NOT NULL AND recorded_by = expected_principal_id)",
            name="ck_audience_receipts_recorded",
        ),
        sa.CheckConstraint("expires_at > issued_at", name="ck_audience_receipts_expiry"),
        sa.ForeignKeyConstraint(["consumed_by_run_id"], ["workflow_runs.id"], ondelete="CASCADE"),
        sa.ForeignKeyConstraint(
            ["expected_principal_id"],
            ["users.id"],
        ),
        sa.ForeignKeyConstraint(
            ["intent_id"],
            ["documentation_write_intents.id"],
        ),
        sa.ForeignKeyConstraint(
            ["recorded_by"],
            ["users.id"],
        ),
        sa.ForeignKeyConstraint(["run_id"], ["workflow_runs.id"], ondelete="CASCADE"),
        sa.ForeignKeyConstraint(
            ["workspace_id"],
            ["projects.id"],
        ),
        sa.PrimaryKeyConstraint("id"),
        sa.UniqueConstraint("challenge_id"),
    )
