def _pgvector_available(bind: sa.Connection) -> bool:
    return bool(bind.execute(sa.text("SELECT 1 FROM pg_available_extensions WHERE name = 'vector'")).scalar())


INDEX_TABLE = "knowledge_evidence_index"
VECTOR_TABLE = "knowledge_evidence_vectors"


def _raw_knowledge_evidence_index_postgres() -> None:
    bind = op.get_bind()
    if bind.dialect.name != "postgresql":
        return
    bind.execute(
        sa.text(
            f"""
            CREATE TABLE IF NOT EXISTS {INDEX_TABLE} (
                project_id varchar(36) NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
                evidence_key varchar(128) NOT NULL,
                revision_id varchar(36) NOT NULL,
                span_ordinal integer NOT NULL,
                body_text text NOT NULL,
                body_tsv tsvector GENERATED ALWAYS AS (to_tsvector('simple'::regconfig, body_text)) STORED,
                products text[] NOT NULL DEFAULT '{{}}',
                version text,
                acl_keys text[],
                updated_at timestamp without time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'),
                CONSTRAINT pk_{INDEX_TABLE} PRIMARY KEY (project_id, evidence_key)
            )
            """
        )
    )
    bind.execute(sa.text(f"CREATE INDEX IF NOT EXISTS ix_{INDEX_TABLE}_body_tsv ON {INDEX_TABLE} USING gin (body_tsv)"))
    bind.execute(sa.text(f"CREATE INDEX IF NOT EXISTS ix_{INDEX_TABLE}_acl_keys ON {INDEX_TABLE} USING gin (acl_keys)"))
    bind.execute(sa.text(f"CREATE INDEX IF NOT EXISTS ix_{INDEX_TABLE}_products ON {INDEX_TABLE} USING gin (products)"))
    bind.execute(
        sa.text(f"CREATE INDEX IF NOT EXISTS ix_{INDEX_TABLE}_revision ON {INDEX_TABLE} (project_id, revision_id)")
    )
    if not _pgvector_available(bind):
        return
    bind.execute(sa.text("CREATE EXTENSION IF NOT EXISTS vector"))
    # Untyped ``vector``: each space has its own dimension, and every comparison is
    # restricted to one ``space_key``. Within one Workspace an exact scan is the
    # search; an approximate index is only worth its write cost far above today's sizes.
    bind.execute(
        sa.text(
            f"""
            CREATE TABLE IF NOT EXISTS {VECTOR_TABLE} (
                project_id varchar(36) NOT NULL,
                space_key varchar(64) NOT NULL,
                evidence_key varchar(128) NOT NULL,
                embedding vector NOT NULL,
                CONSTRAINT pk_{VECTOR_TABLE} PRIMARY KEY (project_id, space_key, evidence_key),
                CONSTRAINT fk_{VECTOR_TABLE}_span FOREIGN KEY (project_id, evidence_key)
                    REFERENCES {INDEX_TABLE} (project_id, evidence_key) ON DELETE CASCADE
            )
            """
        )
    )


def _raw_knowledge_temporal_graph_postgres() -> None:
    bind = op.get_bind()
    if bind.dialect.name != "postgresql":
        return
    vectors = _pgvector_available(bind)
    if vectors:
        bind.execute(sa.text("CREATE EXTENSION IF NOT EXISTS vector"))
    embedding = ", embedding vector" if vectors else ""
    bind.execute(
        sa.text(
            f"""
            CREATE TABLE IF NOT EXISTS kg_node (
                project_id varchar(36) NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
                uuid varchar(64) NOT NULL,
                name text NOT NULL,
                group_id varchar(128) NOT NULL,
                summary text,
                labels text[] NOT NULL DEFAULT '{{}}',
                created_at timestamp without time zone{embedding},
                CONSTRAINT pk_kg_node PRIMARY KEY (project_id, uuid)
            )
            """
        )
    )
    bind.execute(
        sa.text(
            f"""
            CREATE TABLE IF NOT EXISTS kg_edge (
                project_id varchar(36) NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
                uuid varchar(64) NOT NULL,
                relation varchar(128) NOT NULL,
                fact text NOT NULL,
                fact_tsv tsvector GENERATED ALWAYS AS
                    (to_tsvector('simple'::regconfig, coalesce(relation, '') || ' ' || coalesce(fact, ''))) STORED,
                episodes text[] NOT NULL DEFAULT '{{}}',
                group_id varchar(128) NOT NULL,
                source_uuid varchar(64) NOT NULL,
                target_uuid varchar(64) NOT NULL,
                created_at timestamp without time zone,
                valid_at timestamp without time zone,
                invalid_at timestamp without time zone,
                expired_at timestamp without time zone{embedding},
                CONSTRAINT pk_kg_edge PRIMARY KEY (project_id, uuid),
                CONSTRAINT fk_kg_edge_source FOREIGN KEY (project_id, source_uuid)
                    REFERENCES kg_node (project_id, uuid) ON DELETE CASCADE,
                CONSTRAINT fk_kg_edge_target FOREIGN KEY (project_id, target_uuid)
                    REFERENCES kg_node (project_id, uuid) ON DELETE CASCADE
            )
            """
        )
    )
    for statement in (
        "CREATE INDEX IF NOT EXISTS ix_kg_node_group ON kg_node (project_id, group_id)",
        "CREATE INDEX IF NOT EXISTS ix_kg_edge_group ON kg_edge (project_id, group_id)",
        "CREATE INDEX IF NOT EXISTS ix_kg_edge_source ON kg_edge (project_id, source_uuid)",
        "CREATE INDEX IF NOT EXISTS ix_kg_edge_target ON kg_edge (project_id, target_uuid)",
        "CREATE INDEX IF NOT EXISTS ix_kg_edge_episodes ON kg_edge USING gin (episodes)",
        "CREATE INDEX IF NOT EXISTS ix_kg_edge_fact_tsv ON kg_edge USING gin (fact_tsv)",
    ):
        bind.execute(sa.text(statement))


